    } else {
      keys = record_keys(entries);
      index = 0;
      rows = [];
      tensor_count = 0;
      parameter_count = 0;
      tensor_bytes = 0;
      metadata = {};
      metadata_present = 0;
      failure = ok(0);
      while lt(index, list_len(keys)) * is_ok(failure) {
